from ute_common_abstract_core.plugin import load_classes_implemented_by_plugins
from ute_common_abstract_core import instance_loader
from ..ltecell import LteCell


def create_cell(cell_id, active_pools):
    """
    Creates cell object according to active_pools

    :param cell_id:
    :param active_pools:
    :return:
    """
    active_pools = [pool for pool in active_pools]  # noqa: C416

    active_pool_classes = [class_implementation for (class_name, class_implementation) in
                           load_classes_implemented_by_plugins('UE_POOLS').items() if class_name in active_pools]

    active_plugins = list(set([active_class.__module__.split('.')[0] for active_class in active_pool_classes]))  # noqa: C403

    if len(active_plugins) == 1:
        active_plugin_cell_classes = [cell_class for (cell_type, cell_class) in
                                      load_classes_implemented_by_plugins('CELL_TYPES').items()
                                      if cell_class.__module__.split('.')[0] == active_plugins[0]]
        if len(active_plugin_cell_classes) == 1:
            cell = instance_loader.create_class_instance(class_object=active_plugin_cell_classes[0],
                                                         constructor_params={'identification': cell_id})
        else:
            cell = LteCell(cell_id)
    else:
        cell = LteCell(cell_id)
    return cell
